"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4050],{5469(e){e.exports=JSON.parse('{"title":"\uc904\uc774\ub294\uac8c \ub354 \ud798\ub4e4\ub2e4","date":"2026-07-21","coverUrl":"/kudzu-based-bench/assets/notion/b8e1ed6a1f433afd.png","html":"<h1 data-notion-block-id=\\"390e548d-8a8e-8065-abf2-dd7d507ab1c7\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"3a3e548d-8a8e-81cf-9155-fd96d1c18335\\" id=\\"3a3e548d-8a8e-81cf-9155-fd96d1c18335\\">\uc904\uc774\ub294\uac8c \ub354 \ud798\ub4e4\ub2e4</h2><a href=\\"https://jakub.kr/writing/less-is-more\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakub.kr/writing/less-is-more</a><p data-notion-block-id=\\"3a3e548d-8a8e-817d-9c2b-ceecffc9b550\\">\ucf54\ub4dc\ub97c \ub9ce\uc774 \uc9dc\ub294 \uac8c \ub2a5\ub825\uc774\ub358 \uc2dc\uc808\uc774 \ub05d\ub0ac\ub2e4\ub294 \ub9d0\uc740 \ud754\ud569\ub2c8\ub2e4. \uc774 \uae00\uc774 \uc88b\uc740 \uac74 \uadf8 \ub2e4\uc74c \ubb38\uc7a5\uc785\ub2c8\ub2e4. \uc88b\uc740 \uac83\uacfc \ub098\uc05c \uac83\uc744 \uac00\ub824\ub0b4\ub294 \ub208\uc774 \ub354 \uc911\uc694\ud574\uc9c0\ub294 \ub3d9\uc2dc\uc5d0 \ub354 \ud76c\uc18c\ud574\uc9c4\ub2e4\ub294 \uac83. \ub354\ud558\uae30\uac00 \uacf5\uc9dc\uac00 \ub420\uc218\ub85d \ube7c\uae30\uc758 \uac12\uc774 \uc624\ub985\ub2c8\ub2e4. \ub2e4\ub9cc \uc88b\uc740 \uc778\ud130\ud398\uc774\uc2a4\uac00 \ub35c\uc5b4\ub0b4\uae30\ub9cc\uc73c\ub85c \ub418\ub294 \uac74 \uc544\ub2d9\ub2c8\ub2e4. \uac19\uc740 \uc800\uc790\uac00 \uc55e\uc11c \uc4f4 <a href=\\"https://ones-to-watch.ethansup.net/news/post/34ae548d-8a8e-8089-b1db-c322e570f0aa\\">UI\ub97c \ub9cc\ub4e4 \ub54c\uc758 \ub514\ud14c\uc77c</a>\uc740 \ubc18\ub300\ub85c \uc791\uc740 \ub514\ud14c\uc77c\uc744 \ub354\ud574 \ud654\uba74\uc774 \ub098\uc544\uc9c0\ub294 \uc790\ub9ac\ub97c \uc9da\uc2b5\ub2c8\ub2e4. \ubb34\uc5c7\uc744 \ube7c\uace0 \ubb34\uc5c7\uc744 \ub354\ud560\uc9c0 \uc544\ub294 \uadf8 \ud310\ub2e8\uc774 \ucde8\ud5a5\uc774\uace0, AI\uac00 \uc2e4\ud589\uc740 \ub300\uc2e0\ud574\ub3c4 \uc544\uc9c1 \ub300\uc2e0 \ubabb \ud558\ub294 \uc790\ub9ac\uc785\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \uadf8 \ud310\ub2e8\uc740 \ud55c \ubc88 \uac16\ucd94\uba74 \ub05d\uc774 \uc544\ub2c8\ub77c, \uc758\uc874\uc131\uacfc \uae30\ubcf8\uae30\ub97c \uc8fc\uae30\uc801\uc73c\ub85c \ub2e4\uc2dc \ubb3b\uace0 \uacc4\uc18d \ubc30\uc6cc\uc57c \uc720\uc9c0\ub41c\ub2e4\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/164e548d-8a8e-80b6-83ab-e98e54c0407f#168e548d-8a8e-8085-806e-c3f848c70e6e\\">\uacc4\uc18d \uac1c\ubc1c\uc744 \uc9c0\uc18d\ud558\uae30 \uc704\ud574\uc11c</a>\uc640 \uc774\uc5b4\uc9d1\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"adad7bae-4274-4dba-a7d2-bbc3763e63ce\\" id=\\"adad7bae-4274-4dba-a7d2-bbc3763e63ce\\">Hydration mismatch \uadf8\ub0e5 \ubb34\uc2dc\ud558\uba74 \uc548\ub418\ub098\uc694?</h2><a href=\\"https://3perf.com/blog/hydration-mismatch/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://3perf.com/blog/hydration-mismatch/</a><p data-notion-block-id=\\"39ae548d-8a8e-8180-8280-eab8cf88862f\\">Hydration mismatch\uac00 \ub098\uba74 React\ub294 \uadf8 \ubd80\ubd84\ub9cc \uace0\uce58\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ubb34\uc2dc\ud574\uc628 \uacbd\uace0 \ud558\ub098\uac00 \uc9c0\ud45c\ub97c \uc870\uc6a9\ud788 \uc65c\uace1\ud558\uace0 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uccb4\uac10\uacfc \uce21\uc815\uc774 \uac08\ub77c\uc9c8 \ub54c \uc758\uc2ec\ud560 \uacf3\uc740 \uc0ac\uc6a9\uc790\uac00 \uc544\ub2c8\ub77c \uc6b0\ub9ac\uac00 \uc9c0\uc6cc\ub454 \uacbd\uace0\ub77c\ub294 \uc774\uc57c\uae30\uc785\ub2c8\ub2e4. \ubbf8\uc2a4\ub9e4\uce58\ub97c \uc560\ucd08\uc5d0 \uc5c6\uc560\ub294 \uc190\uc7a1\uc774\ub85c\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/3a44405a-7dcb-4e30-b2c3-0e024530ea63#6625f4d3-4c19-48e3-9ba2-04abb2a76adf\\">useSyncExternalStore\ub85c hydration \ubd88\uc77c\uce58 \ub9c9\uae30</a>\uac00 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9a3dd06b-4efd-4bee-af9c-d9b4f4b65637\\" id=\\"9a3dd06b-4efd-4bee-af9c-d9b4f4b65637\\">ChatGPT \uc6f9\uc740 \uc5b4\ub5bb\uac8c 10\uc5b5 \uba85\uc744 \uac10\ub2f9\ud558\ub098</h2><a href=\\"https://performance.dev/chatgpt\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://performance.dev/chatgpt</a><p data-notion-block-id=\\"39ae548d-8a8e-8161-9e88-f4e402d0ea39\\">\uc81c\uc77c \ud3c9\ubc94\ud55c \uc120\ud0dd\uc9c0\ub9cc \uace8\ub77c \ub193\uace0 \uae30\ubcf8\uac12 \ud558\ub098\ud558\ub098\ub97c \uc758\uc2ec\ud574 \uc7b0 \uacb0\uacfc\ub77c, \ub290\ub9b0 \uac78 \uc2a4\ud0dd \ud0d3\ud558\ub358 \ubcc0\uba85\uc774 \uc5ec\uae30\uc120 \uc548 \uc12d\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/385e548d-8a8e-81ed-99ea-ef79fb6bceca#28d2f17f-49a7-42c1-a235-9d7f9d1ec026\\">App Router\ub85c \ub290\ub9b0 \uc751\ub2f5\uc744 80% \uc904\uc774\uae30\uae4c\uc9c0</a>\uc640 \ub098\ub780\ud788 \ub450\uba74 \uae30\ubcf8\uac12\uc744 \uc758\uc2ec\ud55c\ub2e4\ub294 \uac8c \ubb34\uc5c7\uc744 \uc7ac\ub294 \uc77c\uc778\uc9c0 \ubcf4\uc785\ub2c8\ub2e4. \uc800\uc790\uc758 \uac00\uc7a5 \ube60\ub978 \uc694\uccad\uc740 \uc548 \ud558\ub294 \uc694\uccad\uc774\ub77c\ub294 \ud55c \uc904\uc740 \ub85c\ub529\uc5d0\ub3c4 \uc62e\uaca8\uc838, \ubbf8\ub9ac \ubc1b\uc544\ub458 \uc218 \uc788\uc73c\uba74 \ud504\ub9ac\ub85c\ub4dc\ub85c \uc9c0\uc6b0\uace0(<a href=\\"https://ones-to-watch.ethansup.net/news/post/374e548d-8a8e-80ac-9a0c-fa8de4b46b09#378e548d-8a8e-80ec-861a-cce91e9dd6fd\\">\ucd5c\uace0\uc758 \ub85c\ub529 \uc0c1\ud0dc\ub294 \ub85c\ub529\uc774 \uc5c6\ub294 \uac83</a>), \ud655\ub960\uc801\uc774\ub77c \ubabb \ubc1b\uc544\ub450\ub294 \ucc44\ud305 \uc751\ub2f5\ub9cc \uc2a4\ud2b8\ub9ac\ubc0d\uc73c\ub85c \ub4dc\ub7ec\ub0c5\ub2c8\ub2e4. \ucc44\ud305\uc5d0\ub9cc \ud55c\uc815\ub418\ub294 \uc774\uc57c\uae30\uc77c \uc218\ub3c4 \uc788\uc9c0\ub9cc, \ub54c\ub85c\ub294 \uc2a4\ud0dd\ubcf4\ub2e4 \uc5b4\ub5bb\uac8c \uc811\uadfc\ud558\ub290\ub0d0\uac00 \uc911\uc694\ud558\ub2e4\ub294 \uac83\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc608\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"2bc8dd6f-b8f4-4448-99c3-d2396963ddac\\" id=\\"2bc8dd6f-b8f4-4448-99c3-d2396963ddac\\">\ud558\uc774\ub4dc\ub808\uc774\uc158\uacfc \ub80c\ub354\ub9c1 \uc804\ub7b5\ub4e4</h2><a href=\\"https://neciudan.dev/hydration-and-rendering-strategies\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://neciudan.dev/hydration-and-rendering-strategies</a><p data-notion-block-id=\\"39ae548d-8a8e-81ad-acdb-ebdc6ea1c735\\">SSG\ubd80\ud130 \ucd5c\uc2e0 \uae30\ubc95\uae4c\uc9c0, \ub80c\ub354\ub9c1 \uc804\ub7b5\uc744 \ud558\ub098\uc758 \uacc4\ubcf4\ub85c \ud6d1\ub294 \uae00\uc785\ub2c8\ub2e4. \ud504\ub808\uc784\uc6cc\ud06c \ub17c\uc7c1\uc5d0 \ub04c\ub824\uac00\uae30 \uc804\uc5d0 \uc9c0\ud615\uc744 \uba3c\uc800 \ubcf4\uba74 \ub2e4\ud22c\ub294 \uce35\uc704\uac00 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. \ub80c\ub354\ub9c1 \uc804\ub7b5\uc774 \uc774\ub860\uacfc \ub2ec\ub9ac \uc2e4\uc81c \uc694\uccad \ud750\ub984\uc5d0\uc11c \uc5b4\ub514\uc5d0 \ubd80\ub52a\ud788\ub294\uc9c0\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/d4f23197-313d-4572-8daa-b392343947bb\\">RSC \ub610\ud55c \ud3ed\ud3ec \uc694\uccad \ubb38\uc81c\uac00 \uc788\ub2e4</a>\uc640 \ud568\uaed8 \ubcf4\uba74 \uad6c\uccb4\uc801\uc73c\ub85c \uc7a1\ud799\ub2c8\ub2e4. \uacc4\ubcf4\uc758 \ucd9c\ubc1c\uc810\uc778 CSR\ubd80\ud130 \uac01 \uc804\ub7b5\uc744 \uae30\ucd08\ubd80\ud130 \ub2e4\uc2dc \uc9da\uace0 \uc2f6\ub2e4\uba74 <a href=\\"https://www.patterns.dev/react/client-side-rendering/\\">patterns.dev\uc758 \ud074\ub77c\uc774\uc5b8\ud2b8 \uc0ac\uc774\ub4dc \ub80c\ub354\ub9c1 \uc815\ub9ac</a>\uac00 \uc88b\uc740 \ucd9c\ubc1c\uc810\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"84ba8abe-e464-4bdf-a56f-1f3d9fb7b032\\" id=\\"84ba8abe-e464-4bdf-a56f-1f3d9fb7b032\\">React Compiler\ub294 \ub808\ud2b8\ub85c\ud54f\uc785\ub2c8\ub2e4</h2><a href=\\"https://longho.dev/posts/react-compiler-is-a-retrofit/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://longho.dev/posts/react-compiler-is-a-retrofit/</a><p data-notion-block-id=\\"39ae548d-8a8e-81da-b512-f64ee70eda4c\\">\ucef4\ud30c\uc77c\ub7ec\uac00 \ub098\uc058\ub2e4\ub294 \uae00\uc774 \uc544\ub2c8\ub77c, \uc0ac\ud6c4\uc5d0 \uc5b9\ud78c \ucd5c\uc801\ud654\uac00 \uc65c \uadf8\ub807\uac8c \ub9ce\uc740 \uc608\uc678 \uc7a5\uce58\ub97c \ub2ec\uace0 \ub2e4\ub2c8\ub294\uc9c0\ub97c \uc9da\uc2b5\ub2c8\ub2e4. \uba54\ubaa8\uc774\uc81c\uc774\uc158\uc744 \uc131\ub2a5 \ud78c\ud2b8\uac00 \uc544\ub2c8\ub77c \uc544\uc774\ub374\ud2f0\ud2f0\ub97c \ubc14\uafb8\ub294 \uc758\ubbf8\ub860\uc73c\ub85c \ub2e4\uc2dc \ubcf4\uba74, \ucef4\ud30c\uc77c\ub7ec\ub294 \ubb38\uc81c\ub97c \uc5c6\uc560\ub294 \uac8c \uc544\ub2c8\ub77c \uce90\uc2dc\uc758 \uc704\uce58\ub97c \uc62e\uae38 \ubfd0\uc774\ub77c\ub294 \ucabd\uc73c\ub85c \uc0dd\uac01\uc774 \uae30\uc6c1\ub2c8\ub2e4. \uac19\uc740 \ucd5c\uc801\ud654\ub97c Rust\ub85c \uc62e\uaca8 \uc18d\ub3c4\ub9cc \ubc8c\uc5b4\uc628 <a href=\\"https://ones-to-watch.ethansup.net/news/post/385e548d-8a8e-81ed-99ea-ef79fb6bceca\\">React Compiler\uc758 Rust \ud3ec\ud305</a>\uacfc \ub098\ub780\ud788 \ub450\uba74, \ub3c4\uad6c\uac00 \ube68\ub77c\uc9c0\ub294 \uac83\uacfc \ubb38\uc81c\uac00 \ud480\ub9ac\ub294 \uac83\uc774 \ub2e4\ub978 \ucd95\uc774\ub77c\ub294 \uac8c \ubd84\uba85\ud574\uc9d1\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"39ae548d-8a8e-8103-937b-ea934c472493\\" id=\\"39ae548d-8a8e-8103-937b-ea934c472493\\">Astryx: Meta\uac00 8\ub144 \uc4f4 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc744 \uc5f4\uc5c8\uc2b5\ub2c8\ub2e4</h2><a href=\\"https://astryx.atmeta.com/blog/how-astryx-works\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astryx.atmeta.com/blog/how-astryx-works</a><p data-notion-block-id=\\"39ae548d-8a8e-8140-9108-e0af9338a930\\">\ucef4\ud3ec\ub10c\ud2b8 \uac1c\uc218\ub294 \uc911\uc694\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\uc774 \uc0ac\ub78c\uc774 \uc77d\ub294 \ubb38\uc11c\ub97c \ub118\uc5b4 \uc5d0\uc774\uc804\ud2b8\uac00 \uc77d\uace0 \uc4f8 \ud45c\uba74\uc744 1\uae09 \uc694\uad6c\uc0ac\ud56d\uc73c\ub85c \ub4e4\uace0 \ub098\uc654\ub2e4\ub294 \uc0ac\uc2e4\uc774 \uc911\uc694\ud569\ub2c8\ub2e4. \uc55e\uc73c\ub85c \uc0ac\ub0b4 \ud45c\uc900\uc744 \ub9cc\ub4e4 \ub54c \uc9c8\ubb38\uc774 \ud558\ub098 \ub298\ub2c8\ub2e4. \uc774\uac74 \uc5d0\uc774\uc804\ud2b8\uac00 \uc77d\uc744 \uc218 \uc788\ub294\uac00. \uc2a4\ud0dd\ub3c4 \uacf1\uc539\uc744 \ub9cc\ud569\ub2c8\ub2e4. React\uc640 StyleX \uc704\uc5d0 \uc130\ub2e4\ub294 \uac74 styled-components\ub97c \ub5a0\ub098 StyleX\ub85c \uac04 <a href=\\"https://ones-to-watch.ethansup.net/news/post/387e548d-8a8e-80fd-a30f-e35185557443#39de548d-8a8e-8178-8784-fd777102fca7\\">Linear\uc758 \uc774\ub3d9</a>\uacfc \uac19\uc740 \ud750\ub984\uc774\ub77c, \uc774 \uc870\ud569\uc774 \ub300\ud615 \uc2dc\uc2a4\ud15c\uc758 \uae30\ubcf8\uac12 \ucabd\uc73c\ub85c \uad73\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ec6677c9-336e-4fe9-9e50-2519acb14c5d\\" id=\\"ec6677c9-336e-4fe9-9e50-2519acb14c5d\\">\ubb34\uc2ec\ucf54 \uc790\ub3d9\ud654\ud55c npm \ubc30\ud3ec \ud30c\uc774\ud504\ub77c\uc778\uc744 \ub2e4\uc2dc \ubd05\ub2c8\ub2e4</h2><a href=\\"https://www.vlt.io/blog/packument-size-limits\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.vlt.io/blog/packument-size-limits</a><a href=\\"https://nuqs.dev/blog/staged-publishing-for-supply-chain-security\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nuqs.dev/blog/staged-publishing-for-supply-chain-security</a><p data-notion-block-id=\\"f88e8c41-f75a-4548-b61c-808930fcf880\\">\ud55c\ucabd\uc740 \uc790\ub3d9\ud654\uac00 \ub9cc\ub4e0 \uc228\uc740 \ube44\uc6a9\uc774\uace0, \ub2e4\ub978 \ucabd\uc740 \uc77c\ubd80\ub7ec \ub418\ub3cc\ub9b0 \ub9c8\ucc30\uc785\ub2c8\ub2e4. \ub450 \uae00\uc774 \uac19\uc740 \uc790\ub9ac\ub97c \uac00\ub9ac\ud0b5\ub2c8\ub2e4. \uc6b0\ub9ac\uac00 \ud55c \ubc88 \uc138\ud305\ud558\uace0 \uc78a\uc740 npm \ubc30\ud3ec \ud30c\uc774\ud504\ub77c\uc778\uc774 \uc0ac\uc2e4\uc740 \ub9e4\ubc88 \ub0b4\ub9ac\ub294 \uacb0\uc815\uc774\ub77c\ub294 \uac83. \ucee4\ubc0b\ub9c8\ub2e4 \ud37c\ube14\ub9ac\uc2dc\uac00 \ub098\uac00\uace0 \uadf8\uac8c \uc0ac\ub78c \uc190 \uc5c6\uc774 npm\uae4c\uc9c0 \uace7\uc7a5 \ub2ff\ub294\ub2e4\uba74, \uadf8\uac8c \ud3b8\uc758\uc778\uc9c0 \ube44\uc6a9\uc778\uc9c0 \uad6c\uba4d\uc778\uc9c0 \uc9c0\uae08 \ub2e4\uc2dc \ubb3c\uc744 \ub9cc\ud569\ub2c8\ub2e4. \uc124\uce58 \ucabd\uc744 \uc7a0\uadfc \uac83\ub9cc\uc73c\ub85c \uacf5\uae09\ub9dd\uc774 \ub05d\ub098\uc9c0 \uc54a\ub294\ub2e4\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/387e548d-8a8e-80fd-a30f-e35185557443#38be548d-8a8e-81ab-aeff-cddd06f331d0\\">postinstall scripts\ub97c \ub9c9\ub294\ub2e4\uace0 \ubcf4\uc548\uc774 \ub05d\ub098\ub0d0</a>\uac00 install \ucabd\uc5d0\uc11c \uac19\uc740 \ub9d0\uc744 \ud569\ub2c8\ub2e4. \ubc29\uc5b4\ub294 \uc124\uce58\ub4e0 \ud37c\ube14\ub9ac\uc2dc\ub4e0 \ud55c \uacb9\uc73c\ub85c \ub05d\ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"390e548d-8a8e-804f-93b6-eb442d31ae4e\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"3a3e548d-8a8e-811f-885e-e8204a4e6bff\\" id=\\"3a3e548d-8a8e-811f-885e-e8204a4e6bff\\">AI\uc640 \ud568\uaed8 \uc77c\ud558\uae30: \uad6c\uccb4\uc801\uc778 \uc0ac\ub840 \ud558\ub098</h2><a href=\\"https://htmx.org/essays/working-with-ai/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://htmx.org/essays/working-with-ai/</a><p data-notion-block-id=\\"3a3e548d-8a8e-812a-b968-e1edc11c61c9\\">AI\ub97c \uc798 \uc4f0\ub294 \ubc95 \uc7a5\ub974\uc758 \uae00\uc740 \ub300\uac1c \uc800\uc790\uac00 \uc774\ubbf8 \uc798\ud558\uace0 \uc788\ub2e4\ub294 \uc99d\uac70\ub85c \ub05d\ub0a9\ub2c8\ub2e4. \uc774 \uae00\uc740 \ub2e4\ub985\ub2c8\ub2e4. \ub098\uc774 \ub4e4\uba70 \uc783\uc740 \uae30\uc5b5\ub825\uacfc \uc9c0\uad6c\ub825\uc744 AI\uac00 \uba54\uc6cc\uc900\ub2e4\uace0 \uc778\uc815\ud558\uba74\uc11c, \ub3d9\uc2dc\uc5d0 \uadf8\uac8c \uc790\uae30 \uc9c0\ub2a5\uc758 \uc804\ubc18\uc801 \ud1f4\ud589\uc744 \ubd80\ucd94\uae30\ub294 \uac83 \uac19\uc544 \ubb34\uc12d\ub2e4\uace0 \uc501\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"79927d67-13e1-4338-92e0-ba3fc24a33f2\\" id=\\"79927d67-13e1-4338-92e0-ba3fc24a33f2\\">\ucee4\uc2a4\ud130\ub9c8\uc774\uc988 \uac00\ub2a5\ud55c select, \uc5b4\ub5bb\uac8c \uc368\uc57c \ud558\ub098\uc694</h2><a href=\\"https://jakearchibald.com/2026/goldilocks-select-height/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jakearchibald.com/2026/goldilocks-select-height/</a><p data-notion-block-id=\\"4c3618ae-8ffe-476b-b901-f7b9347ea741\\">\ucee4\uc2a4\ud130\ub9c8\uc774\uc9d5 \uac00\ub2a5\ud55c select\uac00 \ub4f1\uc7a5\ud588\uc9c0\ub9cc, \ud53c\ucee4 \ub192\uc774 \ud558\ub098 \uc81c\ub300\ub85c \uc7a1\ub294 \uac83\ubd80\ud130 \ub9cc\ub9cc\uce58 \uc54a\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ubdf0\ud3ec\ud2b8 \uc5ec\ubc31\xb7\ucd5c\uc18c/\ucd5c\ub300 \ub192\uc774\xb7\ub4a4\uc9d1\ud798\xb7\uc2a4\ud06c\ub864\uc774 \uc5bd\ud78c \uadf8 \uc870\uac74\ub4e4\uc744 \uc5b4\ub5bb\uac8c \ub2e4\ub904\uc57c \ud558\ub294\uc9c0 \ucd5c\uc885 CSS\uae4c\uc9c0 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. \uc5d4\uc9c4\uc744 \ub9cc\ub4dc\ub294 \uc0ac\ub78c\ub3c4 \ud63c\uc790 \ubabb \ud480\uace0 \ub3d9\ub8cc\uc5d0\uac8c \ubb3c\uc5c8\ub2e4\ub294 \ub300\ubaa9\uc740, \uad00\ub828 CSS\uac00 \uc544\uc9c1 \uc5bc\ub9c8\ub098 \uc124\uc775\uc5c8\ub294\uc9c0\ub3c4 \uac19\uc774 \uc77c\ub7ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"3a3e548d-8a8e-8140-8bf1-e52985e52651\\" id=\\"3a3e548d-8a8e-8140-8bf1-e52985e52651\\">\ube60\ub978 \ud30c\uc11c\ub97c \ub450\uace0 CPU\uac00 \ub180\uace0 \uc788\ub358 \uc774\uc720</h2><a href=\\"https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-13/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-13/</a><p data-notion-block-id=\\"3a3e548d-8a8e-8176-9796-e532b6fe40af\\">\uc54c\uace0\ub9ac\uc998 \uc774\uc57c\uae30\uac00 \uc544\ub2c8\ub77c \ud504\ub85c\uc138\uc2a4\uc640 \ucee4\ub110 \uc0ac\uc774 \uacbd\uacc4 \uc774\uc57c\uae30\ub77c\ub294 \uac8c \uc774 \uae00\uc758 \uac12\uc785\ub2c8\ub2e4. \uc798 \ub9cc\ub4e0 Rust \ud30c\uc11c\ub97c \ub450\uace0\ub3c4 \ub290\ub838\ub2e4\uba74, \ubcd1\ubaa9\uc744 \ud30c\uc11c\ub77c\uace0 \ub118\uaca8\uc9da\uae30 \uc804\uc5d0 \ud504\ub85c\ud30c\uc77c\ubd80\ud130 \ub5a0\uc57c \ud55c\ub2e4\ub294 \ub9d0\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4. \ud0c0\uc774\ud2b8\ud55c \ub8e8\ud504 \uc548\uc758 syscall \ud558\ub098\uac00 \uc5b4\ub5bb\uac8c \ubcbd\uc774 \ub418\ub294\uc9c0 \uc218\uce58\uae4c\uc9c0 \ubd99\uc5ec \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"ee8801e5-910a-49a1-99af-4fee9baeabdb\\" id=\\"ee8801e5-910a-49a1-99af-4fee9baeabdb\\">\uc9c0\uc6cc\ub3c4 \ub418\ub294 useMemo\uc640 \ub0a8\uaca8\uc57c \ud560 useMemo</h2><a href=\\"https://blog.logrocket.com/react-compiler-memoization-what-actually-broke/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.logrocket.com/react-compiler-memoization-what-actually-broke/</a><p data-notion-block-id=\\"faa549ff-af34-4ca2-9681-be3f5dd7509b\\">\ub0a8\uae38 useMemo\uc640 \uc9c0\uc6b8 useMemo\uc758 \uacbd\uacc4\uac00 \uc774 \uae00\uc5d0\uc11c \ucc98\uc74c \ub610\ub837\ud574\uc9d1\ub2c8\ub2e4. \uc55e\uc73c\ub85c \ucf54\ub4dc\uc5d0 \ub0a8\ub294 \ubaa8\ub4e0 useMemo\ub294 \ub098\uc911\uc5d0 \ubcfc \uc0ac\ub78c\uc774 \uc77d\uc5b4\ub0bc \uc774\uc720\uac00 \uc788\uc5b4\uc57c \ud558\uace0, \uadf8 \uc774\uc720\uac00 \uc5c6\uc73c\uba74 \ucef4\ud30c\uc77c\ub7ec\uac00 \uc54c\uc544\uc11c \ud558\ub2c8 \uadf8\ub0e5 \uc18c\uc74c\uc774\ub77c\ub294 \uac81\ub2c8\ub2e4. \uadf8\ub9ac\uace0 \ubc30\uc9c0\ub97c \ubbff\uc9c0 \ub9d0 \uac83.</p><h2 data-notion-block-id=\\"95049b0a-8a9e-4e09-b7aa-63ce5a4e02fb\\" id=\\"95049b0a-8a9e-4e09-b7aa-63ce5a4e02fb\\">GenUI\ub97c \ub514\uc790\uc778\ud55c\ub2e4\ub294 \uac83</h2><a href=\\"https://blog.gskinner.com/archives/2026/06/designing-for-genui-what-changes-when-ai-builds-the-ui.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.gskinner.com/archives/2026/06/designing-for-genui-what-changes-when-ai-builds-the-ui.html</a><p data-notion-block-id=\\"3f759724-b723-436f-816c-ec3fd64ea123\\">GenUI\uac00 \uc608\uce21 \uac00\ub2a5\uc131\uc744 \ubcc0\ub3d9\uc131\uacfc \ub9de\ubc14\uafb8\uace0 \ub290\ub9ac\ub2e4\ub294 \uac83, \uc120\ud615\uc801\uc774\uace0 \uac10\uc0ac\ubc1b\uc544\uc57c \ud558\ub294 \ud750\ub984\uc5d4 \uace0\uc815 \ud50c\ub85c\uc6b0\uac00 \uc5ec\uc804\ud788 \ub0ab\ub2e4\ub294 \uac83\uae4c\uc9c0 \uc2a4\uc2a4\ub85c \ubabb \ubc15\uc2b5\ub2c8\ub2e4. \uadf8\ub7ec\uace0\ub3c4 \ub0a8\ub294 \ubb38\uc7a5\uc740 \ud558\ub098\uc785\ub2c8\ub2e4. \ub514\uc790\uc774\ub108\uac00 \ud654\uba74\uc744 \uadf8\ub9ac\ub294 \uc0ac\ub78c\uc5d0\uc11c, \ud654\uba74\uc774 \uc870\ub9bd\ub418\ub294 \uae30\uc900\uc744 \uc815\ud558\ub294 \uc0ac\ub78c\uc73c\ub85c \ub118\uc5b4\uac04\ub2e4\ub294 \uac83.</p><h2 data-notion-block-id=\\"3a3e548d-8a8e-810f-bf56-d229282ed2ba\\" id=\\"3a3e548d-8a8e-810f-bf56-d229282ed2ba\\">\uac19\uc740 \uc571\uc744 KMP\uc640 React Native\ub85c \ub9cc\ub4e4\uc5b4\ubd24\uc2b5\ub2c8\ub2e4</h2><a href=\\"https://swmansion.com/blog/we-built-the-same-app-in-kmp-and-react-native-here-s-what-we-found/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://swmansion.com/blog/we-built-the-same-app-in-kmp-and-react-native-here-s-what-we-found/</a><h2 data-notion-block-id=\\"82b7ab7e-faef-45e3-97fb-5be78770988d\\" id=\\"82b7ab7e-faef-45e3-97fb-5be78770988d\\">\ubaa8\ubc14\uc77c \ubaa8\ub4c8 \ud398\ub354\ub808\uc774\uc158: \ub7f0\ud0c0\uc784 \ubc30\ud3ec\uac00 \ubcf5\uc7a1\ub3c4 \uac12\uc744 \ud560 \ub54c</h2><a href=\\"https://www.callstack.com/blog/mobile-module-federation-with-re-pack-when-runtime-delivery-is-worth-the-complexity\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.callstack.com/blog/mobile-module-federation-with-re-pack-when-runtime-delivery-is-worth-the-complexity</a><h1 data-notion-block-id=\\"390e548d-8a8e-8050-8484-e800ef183015\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-7-0/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-7-0/</a><p data-notion-block-id=\\"d17eb7ab-b25c-493e-b1c1-ca6bf44c1b44\\">Go\ub85c \ub2e4\uc2dc \uc4f4 \ub124\uc774\ud2f0\ube0c \ud3ec\ud2b8\uac00 7\uc6d4 8\uc77c \uc815\uc2dd \ucd9c\uc2dc\ub410\uc2b5\ub2c8\ub2e4. \uc804\uccb4 \ube4c\ub4dc\uac00 \ud1b5\uc0c1 8~12\ubc30 \ube68\ub77c\uc84c\uc9c0\ub9cc, 7.0\uc740 \ud504\ub85c\uadf8\ub798\ub9e4\ud2f1 API \uc5c6\uc774 \ub098\uc640 typescript-eslint \uac19\uc740 \ub3c4\uad6c\ub294 @typescript/typescript6 \ud638\ud658 \ud328\ud0a4\uc9c0\ub97c \ubcd1\ud589 \uc124\uce58\ud574\uc57c \ud558\uace0 \uc0c8 API\ub294 7.1\uc785\ub2c8\ub2e4.</p><a href=\\"https://expo.dev/changelog/sdk-57\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://expo.dev/changelog/sdk-57</a><p data-notion-block-id=\\"de238d81-7bff-40c2-849f-38706b0c7ca3\\">React Native\ub9cc 0.85\uc5d0\uc11c 0.86\uc73c\ub85c \uc62c\ub9ac\ub294 \ub9b4\ub9ac\uc2a4\ub85c, Expo\uac00 \ud070 SDK \uc0ac\uc774\uc5d0 \uae68\uc9c0\uc9c0 \uc54a\ub294 RN \uc5c5\ub370\uc774\ud2b8\ub97c \ub07c\uc6cc \ub123\ub294 \ucf00\uc774\ub358\uc2a4 \uc2e4\ud5d8\uc785\ub2c8\ub2e4(React\ub294 19.2 \uadf8\ub300\ub85c). reanimated\ub294 \uc784\ud3ec\ud2b8\ub9cc \ud574\ub3c4 \uba54\ubaa8\ub9ac\uac00 25~30% \ub298\uc5b4\ub098\ub294 RN 0.85 Hermes \uc774\uc288\uac00 SDK 56\xb757\uc5d0 \ub2e4 \uc788\uc73c\ub2c8 \uc8fc\uc758\ud558\uc138\uc694.</p><a href=\\"https://github.com/kane50613/takumi/releases/tag/takumi%402.0.0\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/kane50613/takumi/releases/tag/takumi%402.0.0</a><p data-notion-block-id=\\"632c0203-ec82-47fe-a0fb-1a479f6b8da3\\">JSX\xb7HTML\uacfc CSS\ub97c \ud5e4\ub4dc\ub9ac\uc2a4 \ube0c\ub77c\uc6b0\uc800 \uc5c6\uc774 \uc774\ubbf8\uc9c0\ub85c \ub80c\ub354\ub9c1\ud558\ub294 Rust \uc5d4\uc9c4\uc785\ub2c8\ub2e4. 2.0\uc740 HTML\uc744 \uc9c1\uc811 \ud30c\uc2f1\ud558\ub294 \ud06c\ub808\uc774\ud2b8\uc640, @keyframes\ub97c \uc560\ub2c8\uba54\uc774\uc158 WebP\xb7GIF\ub85c \ubf51\ub294 \uc560\ub2c8\uba54\uc774\uc158 \ucd9c\ub825\uc744 \ub354\ud588\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://www.pkgpulse.com/guides/publint-vs-arethetypeswrong-vs-knip-2026\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.pkgpulse.com/guides/publint-vs-arethetypeswrong-vs-knip-2026</a><p data-notion-block-id=\\"645d1f73-85e1-47a2-a51e-b223ef9292f0\\">\uc14b\uc744 \ub300\uccb4\uc7ac\ub85c \uc624\ud574\ud558\ub294 \uc0ac\ub78c\uc774 \ub9ce\uc544 \uc815\ub9ac\ud55c \uae00\uc785\ub2c8\ub2e4. publint\ub294 \ud328\ud0a4\uc9c0 \uba54\ud0c0\ub370\uc774\ud130\uc758 \ubaa8\uc591\uc744, arethetypeswrong\uc740 \uc18c\ube44\uc790\uac00 \ud0c0\uc785\uc744 \uc2e4\uc81c\ub85c \uc5b4\ub5bb\uac8c \ud574\uc11d\ud558\ub294\uc9c0\ub97c, Knip\uc740 \ubc30\ud3ec \uc804\uc5d0 \uc8fd\uc740 \ubb34\uac8c\uac00 \ub0a8\uc558\ub294\uc9c0\ub97c \ubd05\ub2c8\ub2e4. \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud37c\ube14\ub9ac\uc2dc\ud55c\ub2e4\uba74 \uc14b \ub2e4, \ud558\ub098\ub9cc \uace0\ub978\ub2e4\uba74 publint\ubd80\ud130.</p><a href=\\"https://socket.dev/blog/rolldown-pulls-rust-react-compiler-integration\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://socket.dev/blog/rolldown-pulls-rust-react-compiler-integration</a><p data-notion-block-id=\\"3a3e548d-8a8e-8117-81ad-c408ac3619a8\\">Oxc\uc758 Rust React Compiler \ud3ec\ud2b8\ub97c Rolldown\uc5d0 \uc5f0\uacb0\ud558\ub824\ub358 \uc791\uc5c5\uc774 6\uc6d4 9\uc77c \ucca0\ud68c\ub410\uc2b5\ub2c8\ub2e4. \ubc14\uc774\ub108\ub9ac\uac00 28.7MB\uc5d0\uc11c 33.8MB\ub85c 17% \ub298\uace0 \uadf8 \ube44\uc6a9\uc774 React\ub97c \uc548 \uc4f0\ub294 \uc0ac\uc6a9\uc790\uc5d0\uac8c\uae4c\uc9c0 \uae30\ubcf8\uc73c\ub85c \uc2e4\ub9b0\ub2e4\ub294 \uac8c \uc774\uc720\ub85c, \ud504\ub808\uc784\uc6cc\ud06c \uc911\ub9bd\uc774\uc5b4\uc57c \ud55c\ub2e4\ub294 Evan You\uc758 \ubc18\ub860\uc774 \ubc30\uacbd\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"24030965-2225-4820-8b24-50c0431075c8\\" id=\\"24030965-2225-4820-8b24-50c0431075c8\\">\ubc88\uc678: \ucf54\ub529\uc740 \uc5ec\uc804\ud788 \ubc30\uc6b8 \uac00\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4</h2><a href=\\"https://stevekrouse.com/learn-to-code\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://stevekrouse.com/learn-to-code</a><p data-notion-block-id=\\"cfbe27c7-80ff-4441-b895-ead356c8a20d\\">LLM\uc774 \uc601\uc5b4\ub97c \ucf54\ub4dc\ub9cc\ud07c \uc798 \uc4f0\ub294\ub370 \uc544\ubb34\ub3c4 \uc778\ubb38\ud559\uc758 \uc874\ub9bd\uc744 \uac71\uc815\ud558\uc9c0 \uc54a\ub294\ub2e4\ub294 \ud55c \uc904\uc774 \uc774 \uae00\uc758 \uc804\ubd80\uc785\ub2c8\ub2e4. \uc65c \uc5ec\uc804\ud788 \ubc30\uc6cc\uc57c \ud558\ub294\uc9c0\ub97c \uad50\uc721\uc758 \uadfc\uac70\ub85c \ub2f5\ud55c \uc774 \uae00\uc744, \uc815\ubcf4\uac00 \uacf5\uc9dc\uac00 \ub41c \uc2dc\ub300\uc5d0 \uc0ac\ub78c\uc5d0\uac8c \ub0a8\ub294 \uac74 \ud310\ub2e8\uacfc \uc99d\uc5b8\uacfc \ubc29\ud5a5\ubfd0\uc774\ub77c\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/36be548d-8a8e-800f-be7a-f6849a670533#36be548d-8a8e-8063-959a-fbf00e2807c6\\">AI\uc5d0 \ub300\ud55c \uc2dc\ub2c8\uc5b4 \uac1c\ubc1c\uc790\uc758 \uc0dd\uac01</a>\uacfc \ub098\ub780\ud788 \ub450\uba74, \ubc30\uc6c0\uc774 \ud5a5\ud558\ub294 \uc790\ub9ac\uac00 \uc870\uae08 \ub354 \ub610\ub837\ud574\uc9d1\ub2c8\ub2e4.</p>"}')}}]);